import XCTest
import Foundation
@testable import ScreechCore

/// Compatibility with the web implementation (fixtures generated by tools/make-fixtures.mjs from RetroSynths).
final class CompatTests: XCTestCase {
    struct SymbolCase: Decodable { let mode: String; let flags: Int; let payload: [Int]; let tones: [Int] }
    struct NoteCase: Decodable { let file: String; let mode: String; let text: String; let passphrase: String; let flags: Int }
    struct DeflateCase: Decodable { let text: String; let raw: [Int]; let rawBest: [Int]; let textBest: String }

    func testToneSequencesMatchWebExactly() throws {
        let cases = try JSONDecoder().decode([SymbolCase].self, from: Data(contentsOf: fixtures.appendingPathComponent("symbols.json")))
        XCTAssertEqual(cases.count, 12)
        for c in cases {
            let m = try XCTUnwrap(NoteMode.byKey(c.mode))
            let tones = NoteModem.frameSymbols(payload: c.payload.map { UInt8($0) }, flags: c.flags, mode: m)
            XCTAssertEqual(tones, c.tones, "\(c.mode) \(c.payload.count) bytes")
        }
    }

    func testDecodesAndDecryptsWebNotes() throws {
        let cases = try JSONDecoder().decode([NoteCase].self, from: Data(contentsOf: fixtures.appendingPathComponent("notes.json")))
        for c in cases {
            let (s, rate) = try readWav(fixtures.appendingPathComponent(c.file))
            let frames = NoteDecoder.decode(s, sampleRate: rate)
            guard let f = frames.first(where: { if case .frame(true, _, _, _, _, _) = $0 { return true }; return false }),
                  case let .frame(_, _, modeKey, flags, bytes?, _) = f else { XCTFail("no frame in \(c.file)"); continue }
            XCTAssertEqual(modeKey, c.mode)
            XCTAssertEqual(flags, c.flags)
            let m = NoteMode.byKey(modeKey)!
            let st = NoteCrypto.unpack(bytes, flags: flags, passphrase: c.passphrase, modeId: m.id)
            XCTAssertEqual(st, c.passphrase.isEmpty ? .open(c.text) : .secret(c.text), c.file)
            if !c.passphrase.isEmpty {
                XCTAssertEqual(NoteCrypto.unpack(bytes, flags: flags, passphrase: c.passphrase + "x", modeId: m.id), .wrongPassphrase)
                XCTAssertEqual(NoteCrypto.unpack(bytes, flags: flags, passphrase: "", modeId: m.id), .locked)
            }
        }
    }

    func testInflatesBrowserDeflate() throws {
        let c = try JSONDecoder().decode(DeflateCase.self, from: Data(contentsOf: fixtures.appendingPathComponent("deflate.json")))
        XCTAssertEqual(try RawDeflate.decompress(c.raw.map { UInt8($0) }), Array(c.text.utf8))
        XCTAssertEqual(try RawDeflate.decompress(c.rawBest.map { UInt8($0) }), Array(c.textBest.utf8))
    }
}
